typedef struct{const unsigned char*p,*e;} JP;
static void jws(JP*j){while(j->p<j->e&&(*j->p==' '||*j->p=='\n'||*j->p=='\r'||*j->p=='\t'))j->p++;}
static bool jval(JP*j,int depth);
static bool jstr(JP*j){if(j->p>=j->e||*j->p++!='"')return false;while(j->p<j->e){unsigned c=*j->p++;if(c=='"')return true;if(c<0x20)return false;if(c=='\\'){if(j->p>=j->e)return false;c=*j->p++;if(strchr("\"\\/bfnrt",(int)c))continue;if(c!='u'||j->e-j->p<4)return false;for(int i=0;i<4;i++)if(!isxdigit(j->p[i]))return false;j->p+=4;}}return false;}
static bool jnum(JP*j){const unsigned char*s=j->p;if(j->p<j->e&&*j->p=='-')j->p++;if(j->p>=j->e)return false;if(*j->p=='0')j->p++;else{if(!isdigit(*j->p))return false;while(j->p<j->e&&isdigit(*j->p))j->p++;}if(j->p<j->e&&*j->p=='.'){j->p++;if(j->p>=j->e||!isdigit(*j->p))return false;while(j->p<j->e&&isdigit(*j->p))j->p++;}if(j->p<j->e&&(*j->p=='e'||*j->p=='E')){j->p++;if(j->p<j->e&&(*j->p=='+'||*j->p=='-'))j->p++;if(j->p>=j->e||!isdigit(*j->p))return false;while(j->p<j->e&&isdigit(*j->p))j->p++;}return j->p>s;}
static bool jval(JP*j,int d){if(d>128)return false;jws(j);if(j->p>=j->e)return false;if(*j->p=='"')return jstr(j);if(*j->p=='{'){j->p++;jws(j);if(j->p<j->e&&*j->p=='}'){j->p++;return true;}for(;;){jws(j);if(!jstr(j)){return false;}jws(j);if(j->p>=j->e||*j->p++!=':')return false;if(!jval(j,d+1))return false;jws(j);if(j->p>=j->e)return false;if(*j->p=='}'){j->p++;return true;}if(*j->p++!=',')return false;}}if(*j->p=='['){j->p++;jws(j);if(j->p<j->e&&*j->p==']'){j->p++;return true;}for(;;){if(!jval(j,d+1))return false;jws(j);if(j->p>=j->e)return false;if(*j->p==']'){j->p++;return true;}if(*j->p++!=',')return false;}}if(j->e-j->p>=4&&!memcmp(j->p,"true",4)){j->p+=4;return true;}if(j->e-j->p>=5&&!memcmp(j->p,"false",5)){j->p+=5;return true;}if(j->e-j->p>=4&&!memcmp(j->p,"null",4)){j->p+=4;return true;}return jnum(j);}
static bool json_doc(const char*s){if(!s)return false;JP j={(const unsigned char*)s,(const unsigned char*)s+strlen(s)};if(!jval(&j,0))return false;jws(&j);return j.p==j.e;}
static bool ndjson_docs(const char*s,size_t*lines){*lines=0;if(!s)return false;const char*p=s;while(*p){const char*q=strchr(p,'\n');size_t n=q?(size_t)(q-p):strlen(p);if(!n)return false;char*x=darc_strndup(p,n);bool ok=x&&json_doc(x);free(x);if(!ok)return false;(*lines)++;if(!q)break;p=q+1;}return *lines>0;}
/* Strict enough independent XML checker for generated standalone SVG: validates tag nesting, quoting and entities. */
static bool xml_doc(const char*s){if(!s||strncmp(s,"<svg ",5))return false;const char*p=s;char stack[128][16];int sp=0;while(*p){if(*p=='&'){const char*q=strchr(p,';');if(!q||q-p>12)return false;if(strncmp(p,"&amp;",5)&&strncmp(p,"&lt;",4)&&strncmp(p,"&gt;",4)&&strncmp(p,"&quot;",6)&&strncmp(p,"&apos;",6)&&strncmp(p,"&#x",3))return false;p=q+1;continue;}if(*p!='<'){if((unsigned char)*p<0x20&&*p!='\n'&&*p!='\t'&&*p!='\r')return false;p++;continue;}p++;bool close=false;if(*p=='/'){close=true;p++;}char name[16];size_t n=0;while(*p&&(isalnum((unsigned char)*p)||*p==':'||*p=='_')){if(n+1<sizeof name)name[n++]=*p;p++;}name[n]=0;if(!n)return false;if(close){while(*p&&isspace((unsigned char)*p))p++;if(*p++!='>')return false;if(sp<=0||strcmp(stack[sp-1],name))return false;sp--;continue;}bool quote=false;char qc=0,self=false;while(*p){if(quote){if(*p==qc)quote=false;p++;continue;}if(*p=='"'||*p=='\''){quote=true;qc=*p++;continue;}if(*p=='>' ){p++;break;}if(*p=='/'&&p[1]=='>'){self=true;p+=2;break;}p++;}if(quote)return false;if(!self){if(sp>=128)return false;snprintf(stack[sp++],16,"%s",name);}}return sp==0&&strstr(s,"</svg>")!=NULL;}
static long long json_int(const char*s,const char*key,long long def){char pat[96];snprintf(pat,sizeof pat,"\"%s\":",key);const char*p=strstr(s,pat);if(!p)return def;p+=strlen(pat);return strtoll(p,NULL,10);}
static TestProc initr(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc snap(const char*r,const char*s,const char*t){const char*a[]={"./darc","--repo",r,"snapshot","create",s,"--timestamp",t,NULL};return test_exec(a,NULL);}
static TestProc diff(const char*r,const char*a0,const char*b0,const char*fmt,const char*path,const char*const env[]){const char*a[16];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;a[n++]="snapshot";a[n++]="diff";a[n++]=a0;a[n++]=b0;if(path){a[n++]="--path";a[n++]=path;}if(fmt){a[n++]="--format";a[n++]=fmt;}a[n]=NULL;return test_exec(a,env);}
static bool setmtime(const char*p,time_t s){struct timespec t[2]={{s,0},{s,0}};return utimensat(AT_FDCWD,p,t,AT_SYMLINK_NOFOLLOW)==0;}
static int writepat(const char*p,size_t n,unsigned seed){int fd=open(p,O_CREAT|O_TRUNC|O_WRONLY|O_CLOEXEC,0644);if(fd<0)return -1;uint8_t b[65536];size_t off=0;while(off<n){size_t z=n-off<sizeof b?n-off:sizeof b;for(size_t i=0;i<z;i++)b[i]=(uint8_t)(((off+i)*seed)^((off+i)>>9));if(darc_write_all(fd,b,z)){close(fd);return -1;}off+=z;}return close(fd);}

